def load_w0_8p12_sum_matrices():
    payload = base64.b64decode("".join(_W0_8P12_SUM_NPZ_B64))
    with np.load(io.BytesIO(payload), allow_pickle=False) as data:
        return {
        'is58p5_w0_8p12_N6_sum': np.array(data['is58p5_w0_8p12_N6_sum'], dtype=float, copy=True),
        'is58p5_w0_8p12_N78_sum': np.array(data['is58p5_w0_8p12_N78_sum'], dtype=float, copy=True),
        'is58p5_w0_8p12_N200_sum': np.array(data['is58p5_w0_8p12_N200_sum'], dtype=float, copy=True),
        }
